// Function to safely extract the records from the n8n input structure
function getRecords(items) {
    // CRITICAL FIX: The path is set to match the previous node's output: items[0].json.data
    const records = items[0]?.json?.data;

    // Always return an array, even if the data was not found, to prevent "length" errors.
    return Array.isArray(records) ? records : [];
}

// Function to generate the inner HTML table content
function generateHtmlTableContent(records) {
    // 1. Define the intro text (Now part of the overall template)
    const introText = `
    <p style="font-family: Arial, sans-serif; font-size: 14px; margin: 0 0 10px 0;">Hey Johnathan,</p>
    <p style="font-family: Arial, sans-serif; font-size: 14px; margin: 0 0 20px 0;">We have dropped this amount of liquidity from the last day:</p>
    `;

    if (records.length === 0) {
        // Fallback for empty data
        return introText + '<p style="font-family: Arial, sans-serif; color: #dc3545; font-weight: bold;">[ERROR] The report data was empty. Please check the upstream node.</p>';
    }

    // 2. Start the HTML table structure and add header row (NEW Status Column added)
    let htmlTable = `
    <table border="1" cellpadding="10" cellspacing="0" style="width: 100%; max-width: 650px; border-collapse: collapse; border: 1px solid #adb5bd; font-family: Arial, sans-serif; font-size: 13px;">
        <thead style="background-color: #e9ecef;">
            <tr>
                <th style="padding: 12px; text-align: center; border-bottom: 1px solid #adb5bd; width: 50px;">Status</th> 
                <th style="padding: 12px; text-align: left; border-bottom: 1px solid #adb5bd;">Serial No</th>
                <th style="padding: 12px; text-align: left; border-bottom: 1px solid #adb5bd;">Name</th>
                <th style="padding: 12px; text-align: right; border-bottom: 1px solid #adb5bd;">Last Day Drops</th>
            </tr>
        </thead>
        <tbody>
    `;

    // 3. Add data rows
    records.forEach(item => {
        const dropValue = item["Last Day Drops"] ?? 0;

        // Conditional formatting logic for both value and status indicator
        let valueColor, valueTextStyle, statusColor;

        if (dropValue < 0) {
            valueColor = '#dc3545';  // Red for drops
            valueTextStyle = 'font-weight: bold;';
            statusColor = '#dc3545'; // RED for Alert
        } else if (dropValue > 0) {
            valueColor = '#28a745';  // Green for increases
            valueTextStyle = 'font-weight: bold;';
            statusColor = '#28a745'; // GREEN for OK
        } else {
            valueColor = '#343a40';  // Dark Gray/Black for zero change
            valueTextStyle = '';
            statusColor = '#adb5bd'; // GRAY for Neutral
        }

        // HTML for the visual status square
        const statusIndicator = `<div style="width: 16px; height: 16px; background-color: ${statusColor}; margin: 0 auto; border-radius: 3px;"></div>`;

        htmlTable += `
            <tr>
                <td style="padding: 10px; text-align: center; border-top: 1px solid #dee2e6;">${statusIndicator}</td>
                <td style="padding: 10px; text-align: left; border-top: 1px solid #dee2e6;">${item["Serial No"] ?? ''}</td>
                <td style="padding: 10px; text-align: left; border-top: 1px solid #dee2e6;">${item["Name"] ?? ''}</td>
                <td style="padding: 10px; text-align: right; border-top: 1px solid #dee2e6; color: ${valueColor}; ${valueTextStyle}">${dropValue}</td>
            </tr>
        `;
    });

    // 4. Close the table
    htmlTable += `
        </tbody>
    </table>
    `;

    // 5. Combine and return the final HTML string
    return introText + htmlTable;
} 

